    private static func settlement(
        _ id: String,
        title: String,
        company: String,
        brandID: UUID,
        min: Decimal,
        max: Decimal,
        deadlineDays: Int,
        proofRequired: Bool,
        summary: String,
        details: [String],
        payout: String
    ) -> Settlement {
        Settlement(
            id: UUID(uuidString: id)!,
            title: title,
            company: company,
            brandID: brandID,
            eligibleStateCodes: [],
            payoutMin: min,
            payoutMax: max,
            deadline: Calendar.current.date(byAdding: .day, value: deadlineDays, to: .now)!,
            proofRequired: proofRequired,
            qualifiesSummary: summary,
            eligibilityDetails: details,
            claimURL: URL(string: "https://www.ftc.gov/legal-library/browse/cases-proceedings/refunds")!,
            expectedPayoutDate: payout,
            status: .verified,
            isSample: true
        )
    }
